'use strict';
/* A small album of actual people and memories; this view never advances a life. */
const BondsUI=(()=>{
 let selectedId=null,showDeparted=false;
 const number=n=>(Number(n)||0).toLocaleString('th-TH',{maximumFractionDigits:1});
 const brief=(text,limit=110)=>typeof StoryPresentation!=='undefined'?StoryPresentation.short(text,limit):String(text||'').slice(0,limit);
 const people=s=>typeof LifeBonds==='undefined'?[]:LifeBonds.list(s);
 const lastMemory=p=>p.memories?.[0]||null;
 const firstName=p=>String(p.name||'').split(' ')[0];
 const role=p=>String(p.role||'คนที่คุณรู้จัก').split(' · ')[0];
 const memoryText=m=>typeof m==='string'?m:m?.text||'';
 function chosen(s){const all=people(s),visible=all.filter(p=>showDeparted?!p.alive:p.alive);return visible.find(p=>p.id===selectedId)||visible[0]||all.find(p=>p.id===selectedId)||all[0]||null}
 function personPortrait(p,size='small'){return `<canvas class="bonds-portrait ${size}" width="64" height="72" data-bond-portrait="${esc(p.id)}" role="img" aria-label="ภาพพิกเซลของ ${esc(p.name)}"></canvas>`}
 function promiseMarkup(p){const promise=p.promise;if(!promise)return '';const labels={pending:'คำสัญญาที่ยังรออยู่',kept:'คำสัญญาที่ทำได้',fulfilled:'คำสัญญาที่ทำได้',broken:'คำสัญญาที่พลาดไป',missed:'คำสัญญาที่พลาดไป',cancelled:'เรื่องที่ไม่ได้ทำต่อ'};const pending=!['kept','fulfilled','broken','missed','cancelled'].includes(promise.state);return `<div class="bond-promise ${pending?'pending':'resolved'}"><span class="bond-paper-mark" aria-hidden="true">◇</span><div><small>${esc(labels[promise.state]||'คำสัญญาของเรา')}</small><p>${esc(promise.text)}</p>${pending&&Number.isFinite(promise.dueAge)?`<span>นัดไว้เมื่อคุณอายุ ${number(promise.dueAge)} ปี</span>`:''}</div></div>`}
 function panel(s){const all=people(s);if(!all.length)return '';const living=all.filter(p=>p.alive),withPromise=living.find(p=>p.promise&&!['kept','fulfilled','broken','missed','cancelled'].includes(p.promise.state));const remembered=[...all].filter(p=>lastMemory(p)).sort((a,b)=>(lastMemory(b)?.age||0)-(lastMemory(a)?.age||0));const p=withPromise||remembered[0]||living[0]||all[0],m=lastMemory(p);const text=withPromise?withPromise.promise.text:memoryText(m)||`${firstName(p)} · ${p.dream||p.preference||role(p)}`;return `<section class="panel bonds-digest" aria-label="คนสำคัญในชีวิต"><div class="bonds-digest-portraits" aria-hidden="true">${[p,...living.filter(x=>x.id!==p.id)].slice(0,2).map(x=>personPortrait(x)).join('')}</div><div class="bonds-digest-copy"><small>${withPromise?'ยังมีใครบางคนรอคำสัญญาของคุณ':s.dead?'เรื่องของคุณยังอยู่กับพวกเขา':'คนสำคัญในชีวิต'}</small><p>${esc(brief(text,115))}</p></div><button class="secondary" data-open-bonds="${esc(p.id)}">${withPromise?'ดูคำสัญญา':'คนสำคัญ'} →</button></section>`}
 function remembrance(s){if(typeof LifeBonds==='undefined')return '';const memories=LifeBonds.memorial(s)||[];if(!memories.length)return '';return `<section class="bonds-remembrance" aria-label="ความทรงจำที่ฝากไว้"><span class="bonds-thread" aria-hidden="true">· ✦ ·</span><h3>${s.dead?'คุณอยู่ในความทรงจำของใคร':'คนที่ยังอยู่ในความทรงจำ'}</h3><div>${memories.slice(0,3).map(m=>`<article><b>${esc(m.name)}</b><small>${esc(m.role||RACES[m.race]?.[0]||'')}</small><p>${esc(brief(m.text,170))}</p></article>`).join('')}</div><button class="bonds-text-link" data-open-bonds>เปิดสมุดคนสำคัญ →</button></section>`}
 function card(s,p){const actions=LifeBonds.actionOptions(s,p.id),memories=Array.isArray(p.memories)?p.memories:[],trust=Math.max(0,Math.min(100,Number(p.trust)||0));return `<article class="bond-person-detail ${p.alive?'':'departed'}" id="bondPersonDetail" aria-label="เรื่องของ ${esc(p.name)}"><div class="bond-person-heading">${personPortrait(p,'large')}<div><span class="bonds-person-role">${esc(role(p))}${!p.alive?' · อยู่ในความทรงจำ':''}</span><h3>${esc(p.name)}</h3><p>${esc(RACES[p.race]?.[0]||'')} · ${p.alive?'อายุ':'จากไปเมื่ออายุ'} ${number(p.age)} ปี${KINGDOMS[p.kingdom]?` · ${esc(KINGDOMS[p.kingdom][0])}`:''}</p>${p.status?`<small>${esc(p.status)}</small>`:''}</div></div>${p.alive?`<div class="bond-trust"><label for="bondTrust">ความไว้ใจ <b>${Math.round(trust)} / 100</b></label><progress id="bondTrust" value="${trust}" max="100">${Math.round(trust)}%</progress></div>`:''}${p.dream||p.preference?`<dl class="bond-little-things">${p.dream?`<div><dt>${p.alive?'ความฝันเล็ก ๆ':'ความฝันของเขา'}</dt><dd>${esc(p.dream)}${p.dreamStage===3?'<small class="bond-dream-progress">ทำได้แล้ว · มีคุณช่วยอยู่ในเรื่องนี้</small>':p.dreamStage?`<small class="bond-dream-progress">คืบหน้า ${p.dreamStage} / 3</small>`:''}</dd></div>`:''}${p.preference?`<div><dt>สิ่งที่ชอบ</dt><dd>${esc(p.preference)}</dd></div>`:''}</dl>`:''}${promiseMarkup(p)}${p.alive?`<div class="bond-actions" aria-label="ใช้เวลาด้วยกัน">${actions.map(a=>`<button type="button" data-bond-action="${esc(a.id)}" data-bond-person="${esc(p.id)}" ${a.available?'':'disabled'}><span><b>${esc(a.label)}</b><small>${esc(a.hint||'')}</small>${!a.available&&a.reason?`<em>${esc(a.reason)}</em>`:''}</span><strong>${a.cost?number(a.cost)+' ◈':'ไม่ใช้เงิน'}</strong></button>`).join('')}</div>`:''}${memories.length?`<details class="bond-memory-album" open><summary>สิ่งที่เราเคยผ่านมาด้วยกัน <span>${memories.length}</span></summary><ol>${memories.slice(0,6).map(m=>`<li><small>${Number.isFinite(m.age)?'คุณอายุ '+number(m.age)+' ปี':'ความทรงจำ'}</small><p>${esc(memoryText(m))}</p></li>`).join('')}</ol></details>`:`<div class="bond-memory-empty">${p.alive?'ยังมีที่ว่างสำหรับเรื่องของเราสองคน':'ชื่อของเขายังอยู่ในสมุดเล่มนี้'}</div>`}</article>`}
 function open(personId){const s=state;if(!s||typeof LifeBonds==='undefined')return;if(typeof personId==='string')selectedId=personId;const all=people(s);if(typeof personId==='string'){const requested=all.find(p=>p.id===personId);if(requested)showDeparted=!requested.alive}const p=chosen(s);if(p)selectedId=p.id;const living=all.filter(x=>x.alive),departed=all.filter(x=>!x.alive);const visible=showDeparted?departed:living;modal(`<section class="bonds-dialog"><header class="bonds-heading"><div><span class="eyebrow">สมุดเล่มเล็กของชีวิต</span><h2>คนสำคัญ</h2></div><span class="bonds-thread" aria-hidden="true">♡</span></header><p class="bonds-intro">ความฝัน คำสัญญา และเรื่องเล็ก ๆ ที่จำได้</p><div class="bonds-people-switch" role="group" aria-label="เลือกกลุ่มคน"><button type="button" data-bonds-view="living" aria-pressed="${!showDeparted}">อยู่ในชีวิต ${living.length}</button><button type="button" data-bonds-view="departed" aria-pressed="${showDeparted}" ${departed.length?'':'disabled'}>ในความทรงจำ ${departed.length}</button></div>${visible.length?`<div class="bonds-roster" role="group" aria-label="เลือกคนที่อยากพบ">${visible.map(x=>`<button type="button" data-bond-select="${esc(x.id)}" aria-pressed="${x.id===p?.id}">${personPortrait(x)}<span><b>${esc(firstName(x))}</b><small>${esc(role(x))}</small></span>${x.promise&&!['kept','fulfilled','broken','missed','cancelled'].includes(x.promise.state)?'<i class="bond-promise-dot" aria-label="มีคำสัญญาค้างอยู่"></i>':''}</button>`).join('')}</div>`:'<p class="bonds-no-people">รายชื่อและเรื่องของพวกเขาจะเก็บอยู่ที่นี่</p>'}${p&&visible.some(x=>x.id===p.id)?card(s,p):''}${s.dead?remembrance(s):''}<p class="bonds-action-status" id="bondActionStatus" role="status" aria-live="polite"></p></section>`);
  const root=$('#modalBody');root.querySelectorAll('[data-bonds-view]').forEach(b=>b.onclick=()=>{showDeparted=b.dataset.bondsView==='departed';selectedId=null;open()});root.querySelectorAll('[data-bond-select]').forEach(b=>b.onclick=()=>open(b.dataset.bondSelect));root.querySelectorAll('[data-bond-action]').forEach(b=>b.onclick=()=>{const id=b.dataset.bondPerson,action=b.dataset.bondAction;if(!LifeBonds.act(s,id,action)){const status=$('#bondActionStatus');if(status)status.textContent='ช่วงเวลานี้ยังทำสิ่งนั้นไม่ได้';return}save();clock.reset();render();open(id);const status=$('#bondActionStatus');if(status)status.textContent='เก็บช่วงเวลานี้ไว้ในความทรงจำแล้ว';toast('บันทึกช่วงเวลาที่มีให้กันแล้ว')});bind(root,s);
 }
 function paint(root,s){if(typeof Illustration==='undefined')return;const all=people(s);root.querySelectorAll('[data-bond-portrait]').forEach(c=>{const p=all.find(x=>x.id===c.dataset.bondPortrait);if(!p)return;const actual=s.household?.members?.find(m=>m.id===p.memberId||m.id===p.id);const member=actual||{...p,ageAtBirth:(p.age||0)-(s.age||0),deathAge:p.age,look:p.look||{hair:0,coat:0,eyes:0}};Illustration.drawKin(c,s,member)})}
 function bind(root=document,s=state){root.querySelectorAll('[data-open-bonds]').forEach(b=>b.onclick=()=>open(b.dataset.openBonds||undefined));const button=root.querySelector('#lifeBonds');if(button)button.onclick=()=>open();paint(root,s)}
 return {panel,render:panel,open,bind,remembrance};
})();
